<template>
    <section>
        <div class="my-popups">
            <div class="modal d-block ">
                <div class="modal-dialog modal-dialog-centered ui-draggable">
                    <div class="modal-content">
                        <div class="modal-header ui-draggable-handle py-1 ">
                            <h4 name="header" class="modal-title mt-2 pt-2 mb-2">
                                {{ $t('ResetPasswordHeading') }}
                            </h4>
                            <button class="close" v-on:click="ClosePopUp"><em aria-hidden="true"
                                    class="fa fa-times"></em>
                            </button>
                            <span class="user-guide p-2 ">
                                <a class="ancuserguide text-white" data-toggle="collapse" href="#collapseReplyUG"
                                    role="button" aria-expanded="false" aria-controls="collapseExample"> <em
                                        class="fa fa-files-o pr-2"></em>User Guide</a>
                                <div id="collapseReplyUG" class="divancuserguide collapse overflow-auto">
                                    <div id="scrollbarreplyuserguideMangeView" class="custom-scrollbar-js">
                                        <div class="con" v-html="$t('UserGuideResetPassword')"></div>
                                    </div>
                                </div>
                            </span>
                        </div>
                        <div class="listing py-3 px-3">
                            <loader :is-visible="isLoading"></loader>
                            <dynamic-form lang="en" ref="refResetPassword" :buttons="buttons"
                                :schema="FormSchema"></dynamic-form>
                        </div>

                    </div>
                </div>
            </div>
        </div>
    </section>
</template>

<script>
import DataService from '../../services/DataService';
export default {
    props: {
        UserResetPasswordData: {
            type: Object
        }
    },
    data() {
        return {

            ResetPasswordByAdmin: [],
            token: null,
            FormSchema: [],
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success save",
                    text: "<i class='fa fa-save pr-2'></i>Reset Password",
                    onClick: this.onSubmit
                },
                {
                    type: "submit",
                    class: "btn btn-primary disabled",
                    text: "<i class='fa fa-key pr-2'></i>Random Password",
                    onClick: this.GenerateRandomPassword
                }
            ],
            isLoading: false,
            MaxLength: null,
            MinLength: null,
            IsUpperCaseRequired: null,
            IsLowerCaseRequired: null,
            IsNumberRequired: null,
            IsSpacialCharacterRequired: null,
            UppercaseLength: null,
            LowercaseLength: null,
            NumberLength: null,
            SpacialCharacterLength: null,
            BlackListPassword: null,
            FirstName: null,
            LastName: null,
            Email: null,
            PersonalInfo: null,

        }
    },
    async created() {

        var vm = this;
        vm.token = this.GetUserInfo.Token;


        // 1️⃣ Get password policy first
        await vm.GetPasswordPolicyByCompanyId();

        // 2️⃣ Build schema AFTER min/max available
        vm.buildFormSchema();

        // 3️⃣ Set email value safely
        vm.FormSchema[0].Data[0].value = vm.UserResetPasswordData.email_id;
        vm.FirstName = vm.UserResetPasswordData.first_name;
        vm.LastName = vm.UserResetPasswordData.last_name;
        vm.Email = vm.UserResetPasswordData.email_id;
    },

    methods: {
        buildFormSchema() {
            const vm = this;

            vm.FormSchema = [
                {
                    layoutType: "triple",
                    Data: [

                        {
                            astype: "TextField",
                            label: this.$t('Email'),
                            name: "Email",
                            value: "",
                            placeholder: "Enter Title",
                            visibility: true,
                            config: {
                                options: [],
                                showAddIcon: false,
                            },
                            disabled: true,
                            validationRules: "",
                        },
                        {
                            astype: "PasswordField",
                            label: this.$t('NewPassword'),
                            name: "NewPassword",
                            value: "",
                            placeholder: "Enter New Password",
                            visibility: true,
                            config: {
                                options: [],
                                showAddIcon: false,
                            },
                            validationRules: {
                                'required': true,
                                'min': this.MinLength,
                                'max': this.MaxLength,
                                //'regex': /^(?=.*[a-zA-Z])(?=.*\d)(?=.*[!@#$%^&*()_+{}\[\]:;"'<>,.?/\\|`~]).*$/
                            },
                        },
                        {
                            astype: "PasswordField",
                            label: this.$t('ConfirmPassword'),
                            name: "ConfirmPassword",
                            value: "",
                            placeholder: "Enter Confirm Password",
                            visibility: true,
                            config: {
                                options: [],
                                showAddIcon: false,
                            },
                            validationRules: {
                                'required': true,
                                'min': this.MinLength,
                                'max': this.MaxLength,
                                //'regex': /^(?=.*[a-zA-Z])(?=.*\d)(?=.*[!@#$%^&*()_+{}\[\]:;"'<>,.?/\\|`~]).*$/
                            },
                        }
                    ]
                }
            ];
        },
        ClosePopUp() {
            var vm = this;
            vm.$parent.CloseUserResetPasswordPopUp();
        },
        validatePassword(password) {
            debugger
            var vm = this;

            let upperCount = (password.match(/[A-Z]/g) || []).length;
            let lowerCount = (password.match(/[a-z]/g) || []).length;
            let numberCount = (password.match(/[0-9]/g) || []).length;
            let specialCount = (password.match(/[!@#$%^&*()_+{}\[\]:;"'<>,.?/\\|`~]/g) || []).length;

            if (vm.IsUpperCaseRequired && upperCount < vm.UppercaseLength) {
                return `Password must contain at least ${vm.UppercaseLength} uppercase letter(s)`;
            }

            if (vm.IsLowerCaseRequired && lowerCount < vm.LowercaseLength) {
                return `Password must contain at least ${vm.LowercaseLength} lowercase letter(s)`;
            }

            if (vm.IsNumberRequired && numberCount < vm.NumberLength) {
                return `Password must contain at least ${vm.NumberLength} number(s)`;
            }

            if (vm.IsSpacialCharacterRequired && specialCount < vm.SpacialCharacterLength) {
                return `Password must contain at least ${vm.SpacialCharacterLength} special character(s)`;
            }

            // ✅ 5️⃣ 👉 ADD BLACKLIST HERE (LAST)
            if (vm.BlackListPassword) {

                const blackListArray = vm.BlackListPassword
                    .toLowerCase()
                    .split(',')
                    .map(x => x.trim());

                const lowerPassword = password.toLowerCase();

                const found = blackListArray.find(word => word && lowerPassword.includes(word));

                if (found) {
                    return `Password cannot contain "${found}"`;
                }
            }

            // ✅ 6️⃣ Personal Info Validation
            if (!vm.PersonalInfo) {

                const lowerPassword = password.toLowerCase();

                const personalData = [
                    vm.FirstName,
                    vm.LastName,
                    vm.Email
                ]
                    .filter(x => x) // remove null/empty
                    .map(x => x.toLowerCase());

                const found = personalData.find(value => lowerPassword.includes(value));

                if (found) {
                    return `Password cannot contain your personal information`;
                }
            }

            return null;
        },
        async onSubmit(event, data) {

            var vm = this;
            vm.$refs.refResetPassword.validateForm.validate().then(async function (valid) {
                if (valid) {
                    const newPassword = vm.FormSchema[0].Data[1].value;
                    const confirmPassword = vm.FormSchema[0].Data[2].value;

                    // const newPassword = event.NewPassword;
                    // const confirmPassword = event.ConfirmPassword;
                    //const specialChars = /[!@#$%^&*(),.?":{}|<>]/

                    if (newPassword !== confirmPassword) {

                        //alert(this.$t('Passwords do not match!'));
                        vm.ShowAlert(vm.$t("Passwords do not match Please enter the correct password!"), "danger", vm.$t('Alert'));

                        return;
                    }
                    else if (newPassword == confirmPassword) {

                        //alert(this.$t('Passwords  match!'));
                        //return;
                    }
                    // ✅ 2. 👉 ADD YOUR CUSTOM PASSWORD VALIDATION HERE
                    const errorMsg = vm.validatePassword(newPassword);

                    if (errorMsg) {
                        vm.ShowAlert(errorMsg, "danger", vm.$t('Alert'));
                        return;
                    }
                    vm.isLoading = true;
                    try {
                        //const url = `UserId=${vm.UserResetPasswordData.user_id}&Email=${vm.UserResetPasswordData.email_id}&Token=${vm.token}&NewPassword=${newPassword}&ConfirmPassword=${confirmPassword}`;
                        let AdminResetPasswordModel = {
                            UserId: vm.UserResetPasswordData.user_id,
                            Email: vm.UserResetPasswordData.email_id,
                            Token: vm.token,
                            NewPassword: newPassword,
                            ConfirmPassword: confirmPassword
                        }

                        //const response = await DataService.ResetPasswordByAdmin(url);
                        await DataService.ResetPasswordByAdmin(AdminResetPasswordModel).then(response => {
                            if (response.data.status === 'Success') {
                                vm.ShowAlert(vm.$t("Your password has been reset successfully. Please login with your new password"), "success", vm.$t('Alert'));

                            }
                            console.log(response);
                            vm.isLoading = false;
                            vm.ClosePopUp();
                        })

                    } catch (error) {
                        //console.error(error);
                        vm.isLoading = false;
                    }
                }
            })



        },
        async GetPasswordPolicyByCompanyId() {
            debugger
            var vm = this;
            await DataService.GetPasswordPolicyByCompanyId().then(response => {
                if (response.data != "" && response.data != null && response.data != undefined) {
                    vm.buttons[1].class = response.data.is_generate_random_password_required ? 'btn btn-primary' : 'btn btn-primary disabled';
                    vm.MaxLength = response.data.max_length_pwd;
                    vm.MinLength = response.data.min_length_pwd;
                    vm.IsUpperCaseRequired = response.data.is_uppercase_required;
                    vm.IsLowerCaseRequired = response.data.is_lowercase_required;
                    vm.IsNumberRequired = response.data.is_numbers_required;
                    vm.UppercaseLength = response.data.uppercase_length;
                    vm.LowercaseLength = response.data.lowercase_length;
                    vm.NumberLength = response.data.numbers_length;
                    vm.IsSpacialCharacterRequired = response.data.is_special_characters_required;
                    vm.SpacialCharacterLength = response.data.special_characters_length;
                    vm.BlackListPassword = response.data.black_listed_pwds;
                    vm.PersonalInfo = response.data.is_personal_info_allowed;

                }
            }).catch(err => {
                console.log(err);
            })
        },
        GenerateRandomPassword(x, y) {
            var vm = this;
            var temp = {
                UserId: vm.UserResetPasswordData.user_id,
                Email: vm.UserResetPasswordData.email_id,
                Token: "",
                NewPassword: vm.FormSchema[0].Data[1].value,
                ConfirmPassword: vm.FormSchema[0].Data[2].value
            }
            vm.isLoading = true;
            DataService.GenerateRandomPassword(temp).then(response => {
                if (response.data.status == 0 && response.data.result == 'Email') {
                    vm.ShowAlert(vm.$t("RandomPasswordSuccessMsg"), 'success', true, vm.$t('Alert'));
                } else if (response.data.status != 0 && response.data.result == 'Email') {
                    vm.ShowAlert(vm.$t("RandomPasswordMailFailureMsg", [vm.$t(response.data.password)]), 'failure', true, vm.$t('Alert'));
                }
                else {
                    vm.ShowAlert(vm.$t("AddedError", [vm.$t('User')]), 'failure', true, vm.$t('Alert'));
                }
                vm.isLoading = false;
            }).catch(err => {
                console.log(err);
            })
        }
        // GenerateRandomPassword() {
        //     const randomPassword = Math.random().toString(36).slice(-8);
        //     this.FormSchema[0].Data[1].value = randomPassword;
        //     this.FormSchema[0].Data[2].value = randomPassword;
        // }
    },

}
</script>